import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';

const AdminPanel = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [dashboardStats, setDashboardStats] = useState({});
  const [users, setUsers] = useState([]);
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        switch(activeTab) {
          case 'dashboard':
            const statsResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/dashboard`, {
              headers: {
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              }
            });
            const statsData = await statsResponse.json();
            setDashboardStats(statsData);
            break;

          case 'users':
            const usersResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/users`, {
              headers: {
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              }
            });
            const usersData = await usersResponse.json();
            setUsers(usersData.users || []);
            break;

          case 'items':
            const itemsResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/admin/items`, {
              headers: {
                'Authorization': `Bearer ${localStorage.getItem('token')}`
              }
            });
            const itemsData = await itemsResponse.json();
            setItems(itemsData || []);
            break;
        }
      } catch (error) {
        console.error('Error fetching admin data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [activeTab]);

  const renderDashboard = () => (
    <div className="admin-dashboard">
      <h3>Dashboard</h3>
      <div className="dashboard-stats">
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.totalUsers}</div>
          <div className="stat-label">Total Users</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.totalItems}</div>
          <div className="stat-label">Total Items</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.totalCoinflips}</div>
          <div className="stat-label">Total Coinflips</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.totalBlackjackGames}</div>
          <div className="stat-label">Total Blackjack Games</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.totalTransactions}</div>
          <div className="stat-label">Total Transactions</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.dailyActiveUsers}</div>
          <div className="stat-label">Daily Active Users</div>
        </div>
        <div className="stat-card">
          <div className="stat-value">{dashboardStats.totalBalance?.toLocaleString()}</div>
          <div className="stat-label">Total Balance (AMP)</div>
        </div>
      </div>
    </div>
  );

  const renderUsers = () => (
    <div className="admin-users">
      <h3>Users Management</h3>
      <table className="table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Username</th>
            <th>Email</th>
            <th>Balance</th>
            <th>Status</th>
            <th>Created</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {users.map((user) => (
            <tr key={user.id}>
              <td>{user.robloxUserId}</td>
              <td>{user.displayName}</td>
              <td>{user.email}</td>
              <td>{user.balance?.toLocaleString()} AMP</td>
              <td>
                <span className={`status-badge ${user.isActive ? 'active' : 'inactive'}`}>
                  {user.isActive ? 'Active' : 'Inactive'}
                </span>
              </td>
              <td>{new Date(user.createdAt).toLocaleDateString()}</td>
              <td>
                <button className="btn btn-sm btn-secondary">View</button>
                <button className="btn btn-sm btn-warning">Edit</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  const renderItems = () => (
    <div className="admin-items">
      <h3>Items Management</h3>
      <table className="table">
        <thead>
          <tr>
            <th>Name</th>
            <th>Description</th>
            <th>Rarity</th>
            <th>Value</th>
            <th>Enabled</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {items.map((item) => (
            <tr key={item.id}>
              <td>{item.name}</td>
              <td>{item.description}</td>
              <td>
                <span className={`badge badge-${item.rarity}`}>
                  {item.rarity}
                </span>
              </td>
              <td>{item.value?.toLocaleString()} AMP</td>
              <td>
                <span className={`status-badge ${item.isEnabled ? 'active' : 'inactive'}`}>
                  {item.isEnabled ? 'Yes' : 'No'}
                </span>
              </td>
              <td>
                <button className="btn btn-sm btn-secondary">Edit</button>
                <button className="btn btn-sm btn-danger">Delete</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading admin panel...</p>
      </div>
    );
  }

  return (
    <div className="admin-panel">
      <div className="page-header">
        <h1>Admin Panel</h1>
      </div>

      <div className="admin-tabs">
        <button 
          className={`tab-button ${activeTab === 'dashboard' ? 'active' : ''}`}
          onClick={() => setActiveTab('dashboard')}
        >
          Dashboard
        </button>
        <button 
          className={`tab-button ${activeTab === 'users' ? 'active' : ''}`}
          onClick={() => setActiveTab('users')}
        >
          Users
        </button>
        <button 
          className={`tab-button ${activeTab === 'items' ? 'active' : ''}`}
          onClick={() => setActiveTab('items')}
        >
          Items
        </button>
        <button 
          className={`tab-button ${activeTab === 'coinflips' ? 'active' : ''}`}
          onClick={() => setActiveTab('coinflips')}
        >
          Coinflips
        </button>
        <button 
          className={`tab-button ${activeTab === 'blackjack' ? 'active' : ''}`}
          onClick={() => setActiveTab('blackjack')}
        >
          Blackjack
        </button>
        <button 
          className={`tab-button ${activeTab === 'transactions' ? 'active' : ''}`}
          onClick={() => setActiveTab('transactions')}
        >
          Transactions
        </button>
        <button 
          className={`tab-button ${activeTab === 'taxes' ? 'active' : ''}`}
          onClick={() => setActiveTab('taxes')}
        >
          Taxes
        </button>
        <button 
          className={`tab-button ${activeTab === 'settings' ? 'active' : ''}`}
          onClick={() => setActiveTab('settings')}
        >
          Settings
        </button>
      </div>

      <div className="tab-content">
        {activeTab === 'dashboard' && renderDashboard()}
        {activeTab === 'users' && renderUsers()}
        {activeTab === 'items' && renderItems()}
        {activeTab === 'coinflips' && <div>Coinflip management section</div>}
        {activeTab === 'blackjack' && <div>Blackjack management section</div>}
        {activeTab === 'transactions' && <div>Transaction management section</div>}
        {activeTab === 'taxes' && <div>Tax configuration section</div>}
        {activeTab === 'settings' && <div>System settings section</div>}
      </div>
    </div>
  );
};

export default AdminPanel;
